// Validate and normalise the incoming IDE payload.
const body = $input.item.json.body || $input.item.json;

if (!body.file_path && !body.description) {
  throw new Error('Payload must include at least one of: file_path, description');
}

const today     = new Date().toISOString().split('T')[0];
const safeTitle = (body.file_path || body.description || 'session')
  .replace(/[^a-zA-Z0-9_\-\.]/g, '_')
  .replace(/^_+|_+$/g, '')
  .substring(0, 60);

const sharedCtx = {
  file_path:    body.file_path    || '',
  language:     body.language     || 'unknown',
  description:  body.description  || '',
  changed_code: body.changed_code || '',
  today:        today,
  safe_title:   safeTitle,
  vault_path:   $env.VAULT_PATH   || '/vault',
  ollama_url:   $env.OLLAMA_URL   || 'http://ollama:11434',
  ollama_model: $env.OLLAMA_MODEL || 'deepseek-r1:7b'
};

return [{ json: sharedCtx }];

// Write a session log entry so there is an audit trail.
const ctx     = $input.item.json;
const logDir  = `${ctx.vault_path}/logs`;
const logFile = `${logDir}/${ctx.today}_session_log.md`;

return [{
  json: {
    ...ctx,
    log_dir:  logDir,
    log_file: logFile,
    log_entry: `---
title: "Session Log ${ctx.today}"
date: ${ctx.today}
tags: [log, session]
related: []
source: "orchestrator"
type: "log"
---

## ${new Date().toISOString()}

- **File:** ${ctx.file_path}
- **Language:** ${ctx.language}
- **Description:** ${ctx.description}
`
  }
}];

// Fan-out: emit the shared context once — downstream branches each pick it up.
const ctx = $('Validate & Normalise Input').item.json;
return [{ json: ctx }];

// Collect results from Documenter and Researcher.
// n8n parallel branches converge here via the Merge node.
return [$input.item];

// Build the new_notes array for the Linker from the two agent responses.
const items = $input.all();
const ctx   = $('Validate & Normalise Input').item.json;

const newNotes = items
  .map(i => i.json)
  .filter(r => r.note_path)
  .map(r => ({ path: r.note_path, title: r.title || '', type: r.agent || 'unknown' }));

return [{
  json: {
    ...ctx,
    new_notes: newNotes
  }
}];

const ctx      = $('Validate & Normalise Input').item.json;
const linkerRes= $input.item.json;

return [{
  json: {
    status:      'complete',
    session_date: ctx.today,
    file_path:   ctx.file_path,
    language:    ctx.language,
    linker:      linkerRes
  }
}];
